// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.cognitive.planner/** * NOUS — Dependency Graph (Module 7 v2 — Step 7.3). * * Builds a topological sort of sub-tasks + detects parallel groups. * Pure functions — fully testable without Android or LLM. * * ## What it does * * Given a list of sub-task IDs + a dependency map (task → tasks it depends on): *  1. **Topological sort** — order tasks so dependencies run first. *  2. **Cycle detection** — if A depends on B and B depends on A, error. *  3. **Parallel group detection** — tasks with no inter-dependencies can run *     simultaneously (e.g., [flights, hotels, weather] in parallel; then *     [budget] which depends on all three). * * ## Example * * ``` * Tasks: [flights, hotels, weather, budget, itinerary] * Dependencies: budget → [flights, hotels], itinerary → [weather, budget] * * Topological sort: [flights, hotels, weather] → [budget] → [itinerary] * Parallel groups: [[flights, hotels, weather], [budget], [itinerary]] * ``` * * @see <a href="docs/strategy/module-7-cognitive-strategy-v2.md">§TaskPlanner</a> */object DependencyGraph {    /**     * Topological sort of [subTaskIds] given [dependencies].     *     * Uses Kahn's algorithm (BFS-based) — O(V + E).     *     * @param subTaskIds all sub-task IDs.     * @param dependencies maps task ID → list of task IDs it depends on.     * @return topologically sorted list, or null if a cycle is detected.     */    fun topologicalSort(        subTaskIds: List<String>,        dependencies: Map<String, List<String>>,    ): List<String>? {        if (subTaskIds.isEmpty()) return emptyList()        // Build in-degree map (how many tasks each task depends on).        val inDegree = subTaskIds.associateWith { 0 }.toMutableMap()        val dependents = subTaskIds.associateWith { mutableListOf<String>() }.toMutableMap()        for ((task, deps) in dependencies) {            if (task !in inDegree) continue            for (dep in deps) {                if (dep !in inDegree) continue  // unknown dependency — skip                inDegree[task] = (inDegree[task] ?: 0) + 1                dependents[dep]?.add(task)            }        }        // Start with tasks that have no dependencies (in-degree = 0).        val queue = ArrayDeque<String>()        for ((task, degree) in inDegree) {            if (degree == 0) queue.add(task)        }        val result = mutableListOf<String>()        while (queue.isNotEmpty()) {            val current = queue.removeFirst()            result.add(current)            for (dependent in dependents[current] ?: emptyList()) {                inDegree[dependent] = (inDegree[dependent] ?: 1) - 1                if (inDegree[dependent] == 0) queue.add(dependent)            }        }        // If not all tasks are in the result, there's a cycle.        return if (result.size == subTaskIds.size) result else null    }    /**     * Detect parallel groups — sets of tasks that can run simultaneously.     *     * Tasks in the same group have no inter-dependencies. Groups are     * ordered: group 0 runs first, then group 1, etc.     *     * Uses the topological sort + level assignment (BFS layers).     *     * @param subTaskIds all sub-task IDs.     * @param dependencies maps task ID → list of task IDs it depends on.     * @return ordered list of parallel groups, or null if cycle detected.     */    fun parallelGroups(        subTaskIds: List<String>,        dependencies: Map<String, List<String>>,    ): List<List<String>>? {        val sorted = topologicalSort(subTaskIds, dependencies) ?: return null        // Assign levels: a task's level = max(dep levels) + 1.        val levels = mutableMapOf<String, Int>()        for (task in sorted) {            val deps = dependencies[task] ?: emptyList()            val maxDepLevel = deps.mapNotNull { levels[it] }.maxOrNull() ?: -1            levels[task] = maxDepLevel + 1        }        // Group by level.        val maxLevel = levels.values.maxOrNull() ?: 0        return (0..maxLevel).map { level ->            levels.filter { it.value == level }.keys.toList()        }    }    /**     * Check if the dependency graph has a cycle.     *     * @return true if a cycle exists.     */    fun hasCycle(        subTaskIds: List<String>,        dependencies: Map<String, List<String>>,    ): Boolean {        return topologicalSort(subTaskIds, dependencies) == null    }}